def load_equity():
    numbers = [int(x) / 10000 for x in EQUITY_UPPER.split()]
    size = len(NAMES)
    table = [[0.5] * size for _ in range(size)]
    k = 0
    for i in range(size):
        for j in range(i, size):
            table[i][j] = numbers[k]
            table[j][i] = 1 - numbers[k]
            k += 1
    for i in range(size):
        table[i][i] = 0.5
    return table
